17	export function showMemory(config: Config): MessageActionReturn {
18	  const memoryContent = flattenMemory(config.getUserMemory());
19	  const fileCount = config.getGeminiMdFileCount() || 0;
20	  let content: string;
21	
22	  if (memoryContent.length > 0) {
23	    content = `Current memory content from ${fileCount} file(s):\n\n---\n${memoryContent}\n---`;
24	  } else {
25	    content = 'Memory is currently empty.';
26	  }
27	
28	  return {
29	    type: 'message',
30	    messageType: 'info',
31	    content,
32	  };
33	}
