35	export function addMemory(
36	  args?: string,
37	): MessageActionReturn | ToolActionReturn {
38	  if (!args || args.trim() === '') {
39	    return {
40	      type: 'message',
41	      messageType: 'error',
42	      content: 'Usage: /memory add <text to remember>',
43	    };
44	  }
45	  return {
46	    type: 'tool',
47	    toolName: 'save_memory',
48	    toolArgs: { fact: args.trim() },
49	  };
50	}
