52	export async function refreshMemory(
53	  config: Config,
54	): Promise<MessageActionReturn> {
55	  let memoryContent = '';
56	  let fileCount = 0;
57	
58	  if (config.isJitContextEnabled()) {
59	    await config.getMemoryContextManager()?.refresh();
60	    memoryContent = flattenMemory(config.getUserMemory());
61	    fileCount = config.getGeminiMdFileCount();
62	  } else {
63	    const result = await refreshServerHierarchicalMemory(config);
64	    memoryContent = flattenMemory(result.memoryContent);
65	    fileCount = result.fileCount;
66	  }
67	
68	  config.updateSystemInstructionIfInitialized();
69	  let content: string;
70	
71	  if (memoryContent.length > 0) {
72	    content = `Memory reloaded successfully. Loaded ${memoryContent.length} characters from ${fileCount} file(s)`;
73	  } else {
74	    content = 'Memory reloaded successfully. No memory content found';
75	  }
76	
77	  return {
78	    type: 'message',
79	    messageType: 'info',
80	    content,
81	  };
82	}
