104	/**
105	 * Represents a skill found in the extraction inbox.
106	 */
107	export interface InboxSkill {
108	  /** Directory name in the inbox. */
109	  dirName: string;
110	  /** Skill name from SKILL.md frontmatter. */
111	  name: string;
112	  /** Skill description from SKILL.md frontmatter. */
113	  description: string;
114	  /** When the skill was extracted (ISO string), if known. */
115	  extractedAt?: string;
116	}
117	
118	/**
119	 * Scans the skill extraction inbox and returns structured data
120	 * for each extracted skill.
121	 */
122	export async function listInboxSkills(config: Config): Promise<InboxSkill[]> {
123	  const skillsDir = config.storage.getProjectSkillsMemoryDir();
124	
125	  let entries: Array<import('node:fs').Dirent>;
126	  try {
127	    entries = await fs.readdir(skillsDir, { withFileTypes: true });
128	  } catch {
129	    return [];
130	  }
131	
132	  const dirs = entries.filter((e) => e.isDirectory());
133	  if (dirs.length === 0) {
134	    return [];
135	  }
136	
137	  // Load extraction state to get dates
138	  const memoryDir = config.storage.getProjectMemoryTempDir();
139	  const statePath = path.join(memoryDir, '.extraction-state.json');
140	  const state = await readExtractionState(statePath);
141	
142	  // Build a map: skillDirName → extractedAt
143	  const skillDateMap = new Map<string, string>();
144	  for (const run of state.runs) {
145	    for (const skillName of run.skillsCreated) {
146	      skillDateMap.set(skillName, run.runAt);
147	    }
148	  }
149	
150	  const skills: InboxSkill[] = [];
151	  for (const dir of dirs) {
152	    const skillPath = path.join(skillsDir, dir.name, 'SKILL.md');
153	    const skillDef = await loadSkillFromFile(skillPath);
154	    if (!skillDef) continue;
155	
156	    skills.push({
157	      dirName: dir.name,
158	      name: skillDef.name,
159	      description: skillDef.description,
160	      extractedAt: skillDateMap.get(dir.name),
161	    });
162	  }
163	
164	  return skills;
165	}
