167	export type InboxSkillDestination = 'global' | 'project';
168	
169	function isValidInboxSkillDirName(dirName: string): boolean {
170	  return (
171	    dirName.length > 0 &&
172	    dirName !== '.' &&
173	    dirName !== '..' &&
174	    !dirName.includes('/') &&
175	    !dirName.includes('\\')
176	  );
177	}
