179	async function getSkillNameForConflictCheck(
180	  skillDir: string,
181	  fallbackName: string,
182	): Promise<string> {
183	  const skill = await loadSkillFromFile(path.join(skillDir, 'SKILL.md'));
184	  return skill?.name ?? fallbackName;
185	}
