187	/**
188	 * Copies an inbox skill to the target skills directory.
189	 */
190	export async function moveInboxSkill(
191	  config: Config,
192	  dirName: string,
193	  destination: InboxSkillDestination,
194	): Promise<{ success: boolean; message: string }> {
195	  if (!isValidInboxSkillDirName(dirName)) {
196	    return {
197	      success: false,
198	      message: 'Invalid skill name.',
199	    };
200	  }
201	
202	  const skillsDir = config.storage.getProjectSkillsMemoryDir();
203	  const sourcePath = path.join(skillsDir, dirName);
204	
205	  try {
206	    await fs.access(sourcePath);
207	  } catch {
208	    return {
209	      success: false,
210	      message: `Skill "${dirName}" not found in inbox.`,
211	    };
212	  }
213	
214	  const targetBase =
215	    destination === 'global'
216	      ? Storage.getUserSkillsDir()
217	      : config.storage.getProjectSkillsDir();
218	  const targetPath = path.join(targetBase, dirName);
219	  const skillName = await getSkillNameForConflictCheck(sourcePath, dirName);
220	
221	  try {
222	    await fs.access(targetPath);
223	    return {
224	      success: false,
225	      message: `A skill named "${skillName}" already exists in ${destination} skills.`,
226	    };
227	  } catch {
228	    // Target doesn't exist — good
229	  }
230	
231	  const existingTargetSkills = await loadSkillsFromDir(targetBase);
232	  if (existingTargetSkills.some((skill) => skill.name === skillName)) {
233	    return {
234	      success: false,
235	      message: `A skill named "${skillName}" already exists in ${destination} skills.`,
236	    };
237	  }
238	
239	  await fs.mkdir(targetBase, { recursive: true });
240	  await fs.cp(sourcePath, targetPath, { recursive: true });
241	
242	  // Remove from inbox after successful copy
243	  await fs.rm(sourcePath, { recursive: true, force: true });
244	
245	  const label =
246	    destination === 'global' ? '~/.gemini/skills' : '.gemini/skills';
247	  return {
248	    success: true,
249	    message: `Moved "${dirName}" to ${label}.`,
250	  };
251	}
