123	/**
124	 * Attempts to acquire an exclusive lock file using O_CREAT | O_EXCL.
125	 * Returns true if the lock was acquired, false if another instance owns it.
126	 */
127	export async function tryAcquireLock(
128	  lockPath: string,
129	  retries = 1,
130	): Promise<boolean> {
131	  const lockInfo: LockInfo = {
132	    pid: process.pid,
133	    startedAt: new Date().toISOString(),
134	  };
135	
136	  try {
137	    // Atomic create-if-not-exists
138	    const fd = await fs.open(
139	      lockPath,
140	      fsConstants.O_CREAT | fsConstants.O_EXCL | fsConstants.O_WRONLY,
141	    );
142	    try {
143	      await fd.writeFile(JSON.stringify(lockInfo));
144	    } finally {
145	      await fd.close();
146	    }
147	    return true;
148	  } catch (error: unknown) {
149	    if (isNodeError(error) && error.code === 'EEXIST') {
150	      // Lock exists — check if it's stale
151	      if (retries > 0 && (await isLockStale(lockPath))) {
152	        debugLogger.debug('[MemoryService] Cleaning up stale lock file');
153	        await releaseLock(lockPath);
154	        return tryAcquireLock(lockPath, retries - 1);
155	      }
156	      debugLogger.debug(
157	        '[MemoryService] Lock held by another instance, skipping',
158	      );
159	      return false;
160	    }
161	    throw error;
162	  }
163	}
