165	/**
166	 * Checks if a lock file is stale (owner PID is dead or lock is too old).
167	 */
168	export async function isLockStale(lockPath: string): Promise<boolean> {
169	  try {
170	    const content = await fs.readFile(lockPath, 'utf-8');
171	    const parsed: unknown = JSON.parse(content);
172	    if (!isLockInfo(parsed)) {
173	      return true; // Invalid lock data — treat as stale
174	    }
175	    const lockInfo = parsed;
176	
177	    // Check if PID is still alive
178	    try {
179	      process.kill(lockInfo.pid, 0);
180	    } catch {
181	      // PID is dead — lock is stale
182	      return true;
183	    }
184	
185	    // Check if lock is too old
186	    const lockAge = Date.now() - new Date(lockInfo.startedAt).getTime();
187	    if (lockAge > LOCK_STALE_MS) {
188	      return true;
189	    }
190	
191	    return false;
192	  } catch {
193	    // Can't read lock — treat as stale
194	    return true;
195	  }
196	}
