198	/**
199	 * Releases the lock file.
200	 */
201	export async function releaseLock(lockPath: string): Promise<void> {
202	  try {
203	    await fs.unlink(lockPath);
204	  } catch (error: unknown) {
205	    if (isNodeError(error) && error.code === 'ENOENT') {
206	      return; // Already removed
207	    }
208	    debugLogger.warn(
209	      `[MemoryService] Failed to release lock: ${error instanceof Error ? error.message : String(error)}`,
210	    );
211	  }
212	}
