/**
 * Strips a leading git-style `a/` or `b/` prefix from a diff header path.
 * Leaves `/dev/null` (used for file creation/deletion) untouched.
 */
function stripGitPrefix(fileName: string): string {
  if (!fileName || fileName === '/dev/null') {
    return fileName;
  }
  // Remove surrounding quotes some diff tools add, then the a/ or b/ prefix.
  const unquoted = fileName.replace(/^"(.*)"$/, '$1');
  return unquoted.replace(/^[ab]\//, '');
}

/**
 * Determines the target file path (relative to the skill directory) for a patch
 * section, preferring the new file name and falling back to the old one.
 * `null` indicates a section with no usable target (e.g. malformed header).
 */
function resolveSectionTarget(
  patch: StructuredPatch,
  skillDirName: string,
): { relPath: string; isCreate: boolean; isDelete: boolean } | null {
  const oldPath = stripGitPrefix(patch.oldFileName ?? '');
  const newPath = stripGitPrefix(patch.newFileName ?? '');
  const isCreate = oldPath === '/dev/null';
  const isDelete = newPath === '/dev/null';

  let relPath = isDelete ? oldPath : newPath;
  if (!relPath || relPath === '/dev/null') {
    relPath = isDelete ? newPath : oldPath;
  }
  if (!relPath || relPath === '/dev/null') {
    return null;
  }

  // Patches may express targets either relative to the skill directory
  // (e.g. "SKILL.md") or relative to the skills root (e.g. "my-skill/SKILL.md").
  // Normalize the latter to the former.
  const prefix = `${skillDirName}/`;
  if (relPath.startsWith(prefix)) {
    relPath = relPath.slice(prefix.length);
  }

  return { relPath, isCreate, isDelete };
}

/**
 * Resolves a relative path inside a skill directory, rejecting anything that
 * escapes the directory (path traversal protection).
 */
function resolveWithinDir(baseDir: string, relPath: string): string | null {
  if (path.isAbsolute(relPath)) {
    return null;
  }
  const base = path.resolve(baseDir);
  const resolved = path.resolve(base, relPath);
  if (resolved !== base && !resolved.startsWith(base + path.sep)) {
    return null;
  }
  return resolved;
}

/**
 * Parses a patch file's raw text into structured sections. Returns `null` when
 * the text is not a parseable, non-empty patch.
 */
function parsePatchSections(patchText: string): StructuredPatch[] | null {
  let sections: StructuredPatch[];
  try {
    sections = parsePatch(patchText);
  } catch {
    return null;
  }
  const usable = sections.filter((s) => s.hunks && s.hunks.length > 0);
  if (usable.length === 0) {
    return null;
  }
  return usable;
}

/**
 * Builds the display entries for a parsed patch, stripping git-style prefixes
 * from the per-section diff headers.
 */
function buildPatchEntries(
  sections: StructuredPatch[],
  skillDirName: string,
): InboxPatchEntry[] {
  const entries: InboxPatchEntry[] = [];
  for (const section of sections) {
    const target = resolveSectionTarget(section, skillDirName);
    const filePath = target?.relPath ?? '(unknown)';
    const lines: string[] = [
      `--- ${filePath}`,
      `+++ ${filePath}`,
      ...section.hunks.flatMap((hunk) => [
        `@@ -${hunk.oldStart},${hunk.oldLines} +${hunk.newStart},${hunk.newLines} @@`,
        ...hunk.lines,
      ]),
    ];
    entries.push({ filePath, diff: lines.join('\n') });
  }
  return entries;
}

/**
 * Scans the skill extraction inbox for pending patch files and returns
 * structured data for each valid `*.patch` file.
 */
export async function listInboxPatches(config: Config): Promise<InboxPatch[]> {
  const skillsDir = config.storage.getProjectSkillsMemoryDir();

  let entries: Array<import('node:fs').Dirent>;
  try {
    entries = await fs.readdir(skillsDir, { withFileTypes: true });
  } catch {
    return [];
  }

  const patchFiles = entries.filter(
    (e) => e.isFile() && e.name.endsWith('.patch'),
  );
  if (patchFiles.length === 0) {
    return [];
  }

  // Load extraction state to get proposal dates, keyed by patch file name.
  const memoryDir = config.storage.getProjectMemoryTempDir();
  const statePath = path.join(memoryDir, '.extraction-state.json');
  const state = await readExtractionState(statePath);
  const patchDateMap = new Map<string, string>();
  for (const run of state.runs) {
    for (const patchName of run.patchesCreated ?? []) {
      patchDateMap.set(patchName, run.runAt);
    }
  }

  const patches: InboxPatch[] = [];
  for (const file of patchFiles) {
    let patchText: string;
    try {
      patchText = await fs.readFile(path.join(skillsDir, file.name), 'utf-8');
    } catch {
      continue;
    }
    const sections = parsePatchSections(patchText);
    if (!sections) {
      continue;
    }
    const name = file.name.replace(/\.patch$/, '');
    patches.push({
      fileName: file.name,
      name,
      entries: buildPatchEntries(sections, name),
      extractedAt: patchDateMap.get(file.name),
    });
  }

  return patches;
}

/**
 * Locates the installed skill directory that a patch targets. Prefers the
 * project (workspace) skill when it exists and the workspace is trusted,
 * otherwise falls back to the global skill.
 */
async function findTargetSkillDir(
  config: Config,
  skillDirName: string,
): Promise<
  | { dir: string; isProject: boolean }
  | { dir: null; untrustedProjectOnly: boolean }
> {
  const projectDir = path.join(
    config.storage.getProjectSkillsDir(),
    skillDirName,
  );
  const globalDir = path.join(Storage.getUserSkillsDir(), skillDirName);

  const projectExists = await pathExists(projectDir);
  const globalExists = await pathExists(globalDir);
  const trusted =
    typeof config.isTrustedFolder === 'function'
      ? config.isTrustedFolder() !== false
      : true;

  if (projectExists && trusted) {
    return { dir: projectDir, isProject: true };
  }
  if (globalExists) {
    return { dir: globalDir, isProject: false };
  }
  if (projectExists && !trusted) {
    // The only installed copy lives in an untrusted workspace.
    return { dir: null, untrustedProjectOnly: true };
  }
  return { dir: null, untrustedProjectOnly: false };
}

